// Examples: {"amount_cents":50000,"category_code":"software","cfdi_uuid":null,"created_at":"2026-09-12T18:30:00Z","deductible":true,"deductible_source":"category_default","description":"Suscripción anual de diseño","has_cfdi":true,"id":"0199d4a3-2b3c-7e4d-9f50-6b7c8d9e0f12","isr_withheld_cents":0,"iva_cents":8000,"iva_rate":"rate_16","iva_withheld_cents":0,"legend":"Esto es un aproximado. No todos los gastos aplican para tu giro comercial.","operation_kind":null,"paid_on":"2026-09-12","payment_method":"card_debit","regime_code":"612","residential_rent":false,"supplier_kind":null,"supplier_regime":null,"taxpayer_id":"0199d4a2-8f00-7c44-a1b2-3c4d5e6f7a80","updated_at":"2026-09-12T18:30:00Z","warnings":[],"withholding":{"cpa_unverified":false,"explanations":[{"rule_id":"ISR-0","text":"No retienes ISR en esta operación."},{"rule_id":"IVA-1","text":"Tampoco retienes IVA en esta operación."}],"isr_cents":0,"isr_rate":"0","iva_basis":"none","iva_cents":0,"net_cents":58000,"remit_due_on":null,"rule_ids":["ISR-0","IVA-1"],"table_version":"2026.1","withholder":"none"}}
