// Examples: {"iva_rates_allowed":["rate_16","rate_8","rate_0","exempt"],"last_used":{"counterparty_kind":"pm","operation_kind":"professional_services","residential_rent":false,"via_platform":false},"platform_activity":null,"suggested_iva_rate":"rate_16"}
